while pq:
    d, u = heapq.heappop(pq)
    if d > ___[u]:
        continue
    for v, w in g[u]:
        if d + w < dist[v]:
            dist[v] = d + w
            heapq.heappush(pq, (dist[v], v))

while (!pq.isEmpty()) {
    int[] cur = pq.poll();
    int d = cur[0], u = cur[1];
    if (d > ___[u]) continue;
    for (int[] e : g[u]) {
        int v = e[0], nd = d + e[1];
        if (nd < dist[v]) {
            dist[v] = nd;
            pq.add(new int[]{nd, v});
        }
    }
}

while (pq.size() > 0) {
  const [d, u] = pq.pop();
  if (d > ___[u]) continue;
  for (const [v, w] of g[u]) {
    if (d + w < dist[v]) {
      dist[v] = d + w;
      pq.push([dist[v], v]);
    }
  }
}

